returnBook(isbn, member) {
  // Check if member has this book
  if (!this._memberHasBook(member, isbn)) {
    throw new Error(`Member ${member} does not have book with ISBN: ${isbn}`);
  }

  // Remove the loan
  const memberLoans = this.loans.get(member);
  memberLoans.set(isbn, memberLoans.get(isbn) - 1);

  // If no more copies of this book are loaned by this member, remove the entry
  if (memberLoans.get(isbn) === 0) {
    memberLoans.delete(isbn);
  }

  // If member has no more loans, remove the member entry
  if (memberLoans.size === 0) {
    this.loans.delete(member);
  }
}

