placeHold(isbn, member) {
  // Check if ISBN exists
  if (!this.books.has(isbn)) {
    throw new Error(`Unknown ISBN: ${isbn}`);
  }

  // Check if any copies are available
  if (this.available(isbn) > 0) {
    throw new Error(`Book with ISBN ${isbn} is available, cannot place hold`);
  }

  // Check if member already has this book
  if (this._memberHasBook(member, isbn)) {
    throw new Error(`Member ${member} already has book with ISBN: ${isbn}`);
  }

  // Check if member already has a hold on this book
  if (this.holds.has(isbn)) {
    const holdQueue = this.holds.get(isbn);
    if (holdQueue.includes(member)) {
      throw new Error(`Member ${member} already has a hold on book with ISBN: ${isbn}`);
    }
  }

  // Add member to hold queue
  if (!this.holds.has(isbn)) {
    this.holds.set(isbn, []);
  }
  this.holds.get(isbn).push(member);
}

returnBook(isbn, member) {
  // Check if member has this book
  if (!this._memberHasBook(member, isbn)) {
    throw new Error(`Member ${member} does not have book with ISBN: ${isbn}`);
  }

  // Remove the loan
  const memberLoans = this.loans.get(member);
  memberLoans.set(isbn, memberLoans.get(isbn) - 1);

  // If no more copies of this book are loaned by this member, remove the entry
  if (memberLoans.get(isbn) === 0) {
    memberLoans.delete(isbn);
  }

  // If member has no more loans, remove the member entry
  if (memberLoans.size === 0) {
    this.loans.delete(member);
  }

  // Check if there are any holds for this book
  if (this.holds.has(isbn) && this.holds.get(isbn).length > 0) {
    // Assign the book to the first member in the hold queue
    const firstHolder = this.holds.get(isbn).shift();
    this.checkout(isbn, firstHolder);
  }
}

