// Test placeHold with valid parameters
console.log("\nTesting placeHold method...");

// Add a book with only one copy
library.addBook("978-0-111111-11-1", "Test Book", 1);

// Checkout the only copy
library.checkout("978-0-111111-11-1", "Alice");

// Try to place a hold when book is unavailable
library.placeHold("978-0-111111-11-1", "Bob");
console.log("Bob placed hold on Test Book (should work)");

// Try to place another hold
library.placeHold("978-0-111111-11-1", "Charlie");
console.log("Charlie placed hold on Test Book (should work)");

// Check holds queue
const holds = library.holds("978-0-111111-11-1");
console.log("Holds queue (should be Bob, Charlie):", holds);

// Try to place a hold when book is available (should fail)
try {
    library.addBook("978-0-222222-22-2", "Another Book", 1);
    library.checkout("978-0-222222-22-2", "David");
    library.placeHold("978-0-222222-22-2", "Eve");
    console.log("ERROR: Should have thrown an error!");
} catch (e) {
    console.log("Correctly threw error when trying to hold available book:", e.message);
}

// Try to place a hold when member already has the book (should fail)
try {
    library.placeHold("978-0-111111-11-1", "Alice");
    console.log("ERROR: Should have thrown an error!");
} catch (e) {
    console.log("Correctly threw error when member already has the book:", e.message);
}

// Try to place a hold twice for the same member (should fail)
try {
    library.placeHold("978-0-111111-11-1", "Bob");
    console.log("ERROR: Should have thrown an error!");
} catch (e) {
    console.log("Correctly threw error when member already has a hold:", e.message);
}

// Test holds method with unknown ISBN
const unknownHolds = library.holds("unknown-isbn");
console.log("Holds for unknown ISBN (should be empty array):", unknownHolds);

// Test returnBook with holds - should assign to first holder
console.log("\nTesting returnBook with holds...");

// Return the book and check if it goes to the first holder
library.returnBook("978-0-111111-11-1", "Alice");
console.log("Book returned, should go to Bob now");

// Check Bob's loans
console.log("Bob's loans (should have Test Book):", library.getLoans("Bob"));

// Check that Charlie is still in the hold queue
const holdsAfterReturn = library.holds("978-0-111111-11-1");
console.log("Holds queue after return (should be Charlie):", holdsAfterReturn);

// Return the book again
library.returnBook("978-0-111111-11-1", "Bob");
console.log("Book returned again, should go to Charlie now");

// Check Charlie's loans
console.log("Charlie's loans (should have Test Book):", library.getLoans("Charlie"));

// Check that hold queue is now empty
const holdsAfterSecondReturn = library.holds("978-0-111111-11-1");
console.log("Holds queue after second return (should be empty):", holdsAfterSecondReturn);

console.log("\nAll hold tests completed successfully!");

