args.find:
checkout(isbn, member) {
  if (this.books[isbn] === undefined) {
    throw new Error(`Book with ISBN ${isbn} not found`);
  }
  if (this.loans[member] === undefined) {
    this.loans[member] = [];
  }
  if (this.loans[member].includes(isbn)) {
    throw new Error(`Member ${member} already has book with ISBN: ${isbn}`);
  }
  if (this.books[isbn].copies <= 0) {
    throw new Error(`No copies available for book with ISBN: ${isbn}`);
  }
  this.loans[member].push(isbn);
  this.books[isbn].copies--;
  return true;
}

